-- ════════════════════════════════════════════════════════════════════════
-- Hearthrise — THE HARDER TIERS' CATALOGUE  (GENERATED — DO NOT EDIT)
--
--   Generated by tools/gen-ground-tiers.mjs from src/data/hunt-tiers.js GROUND_TIERS. Any hand edit FAILS
--   `node tools/gen-ground-tiers.mjs --check` and tests/hunt-core/hunt-tiers.mjs `catalogue`.
--
-- WHAT: hr_ground_tiers (made by 2027-02-27-hunt-tiers.sql, APPLIED) rewritten whole, 20 rows: per ground and tier the
-- pull, the same for one to four heroes (0 = no more than Normal brings), the monsters' damage and health and the XP a kill pays, permille.
-- Normal is no row and doesn't move. The data holds ONE table for every ground (balance-sheet.js TIER_DIALS, tierRowFor at the
-- ground's floor, named per-ground pulls); this table holds each ground's resolved rows, so every server reader stays one lookup. No function,
-- grant or client verb changes. The server reads the pull when it freezes a hunt and a row's presence when a hero picks it;
-- the engine reads the same numbers from the data, so the hr-accrue deploy carrying this GROUND_TIERS follows AT ONCE (a hunt
-- already running keeps the pull it froze; its blows and its next spawns read the deployed engine).
-- SHAPE (lane/b-tier-dials, Tyler 2026-11-07: a tier is "a scaling % of exp and difficulty BUT NOT GOLD"): power_pm is renamed
-- dmg_pm (the monsters' atk and Level, as before) and hp_pm is new (the monsters' health under the party scale; its kill yield
-- stays the party scale's, so more health pays no more coin or drops). HP and XP stay inside the value bound hr_hunt_apply_member
-- reads (a window's kill XP under K x the most a Normal kill of the ground teaches, K = hr_hunt_limit('value_headroom')); damage
-- moves only Defense XP, whose own term (16 foes a swing x K) holds the 4000 cap at a full box of 8.
-- THIS FILE (lane/d-harder-monsters, Tyler 2026-11-19: "I think we should raise HP and damage done by all monsters in the game slightly.
-- Everything is a bit too easy it seems"): the stat formula's blows and HP line are x1.1 (src/data/balance-sheet.js STAT_FORMULA), every
-- monster row with them. A harder tier is the swing a full ground's tier is worth, read against the ground's own Normal (tierRowFor), so on
-- the two gentle grounds whose tiers lift (the Thicket and Wickstead) the atk scaling that reaches it eases about 1.5%: the Thicket's
-- Dangerous 2711 -> 2672 and Deadly 3433 -> 3377, Wickstead's 2654 -> 2614 and 3351 -> 3295, on monsters a tenth harder at Normal.
-- Every other row is 2027-05-02-flat-party-xp-ground-tiers.generated.sql's, carried whole.
-- ORDER: after 2027-05-02-flat-party-xp-ground-tiers.generated.sql and every 2027-05-22 file (set v0.2.141); no other file writes
-- hr_ground_tiers. Idempotent: the rows are rewritten whole, so a second apply is byte-identical. No begin/commit (CLAUDE.md §2).
-- The hr-accrue deploy carrying the same src/data/balance-sheet.js, src/data/monsters.js and the packs follows AT ONCE (a hunt
-- already running keeps the pull it froze). REVERSIBLE: re-apply 2027-05-02-flat-party-xp-ground-tiers.generated.sql, with the
-- engine from before this lane.
-- ════════════════════════════════════════════════════════════════════════

-- ── §0 PRECONDITIONS ─────────────────────────────────────────────────────────
do $mig$
begin
  if to_regclass('public.hr_ground_tiers') is null then
    raise exception 'PRECONDITION: apply 2027-02-27-hunt-tiers.sql first (the table this file fills)'; end if;
  if to_regclass('public.hr_hunt_grounds') is null or to_regprocedure('public.hr_hunt_limit(text)') is null then
    raise exception 'PRECONDITION: the hunt-sessions catalogue first (hr_hunt_grounds, hr_hunt_limit)'; end if;
end $mig$;

-- ── §1 THE SHAPE: power_pm is dmg_pm, hp_pm is new ───────────────────────────
do $mig$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'hr_ground_tiers' and column_name = 'power_pm') then
    alter table public.hr_ground_tiers rename column power_pm to dmg_pm;
  end if;
end $mig$;
alter table public.hr_ground_tiers add column if not exists hp_pm int;
alter table public.hr_ground_tiers drop constraint if exists hr_ground_tiers_power_pm_check;
alter table public.hr_ground_tiers drop constraint if exists hr_ground_tiers_dmg_pm_check;
alter table public.hr_ground_tiers drop constraint if exists hr_ground_tiers_hp_pm_check;

-- ── §2 THE ROWS ──────────────────────────────────────────────────────────────
comment on table public.hr_ground_tiers is
  '2027-05-26-harder-monsters-ground-tiers.generated.sql: the harder tiers a ground offers (src/data/hunt-tiers.js through tools/gen-ground-tiers.mjs; tests/hunt-core/hunt-tiers.mjs holds the two equal). Per ground and tier: the pull for 1-4 heroes, the monsters'' damage (dmg_pm) and health (hp_pm) and a kill''s Level XP (xp_pm), permille; never coin. Read by hr_hunt_tier_set and the freeze. No row = not offered. Normal is no row.';
delete from public.hr_ground_tiers;
insert into public.hr_ground_tiers (hunt_id, tier, pull, dmg_pm, hp_pm, xp_pm) values
  ('millrace_sewer', 'dangerous', '{0,0,0,0}'::int[], 1170, 1150, 1100),
  ('millrace_sewer', 'deadly', '{0,0,0,0}'::int[], 1330, 1250, 1220),
  ('meadowbrook_thicket', 'dangerous', '{0,0,0,0}'::int[], 2672, 1000, 1050),
  ('meadowbrook_thicket', 'deadly', '{0,0,0,0}'::int[], 3377, 1000, 1080),
  ('coppercap_warrens', 'dangerous', '{8,8,8,8}'::int[], 1170, 1150, 1100),
  ('coppercap_warrens', 'deadly', '{8,8,8,8}'::int[], 1330, 1250, 1250),
  ('mosslight_glade', 'dangerous', '{6,6,6,6}'::int[], 1170, 1400, 1100),
  ('mosslight_glade', 'deadly', '{8,8,8,8}'::int[], 1330, 1450, 1250),
  ('wickstead', 'dangerous', '{0,0,0,0}'::int[], 2614, 1100, 1100),
